aristas = [
    {"desde": "ana", "tipo": "FRIEND_OF", "hasta": "luis", "fuerza": 5},
    {"desde": "ana", "tipo": "FRIEND_OF", "hasta": "sol", "fuerza": 2},
    {"desde": "luis", "tipo": "FRIEND_OF", "hasta": "sol", "fuerza": 4},
    {"desde": "sol", "tipo": "SIGUE", "hasta": "ana", "fuerza": None},
]

def grado(nodo):
    # cuenta aristas conectadas a un nodo; un grado muy alto puede ralentizar traversals
    return sum(1 for a in aristas if a["desde"] == nodo or a["hasta"] == nodo)

def amistades_fuertes(minimo):
    return [(a["desde"], a["hasta"]) for a in aristas if a["tipo"] == "FRIEND_OF" and a["fuerza"] and a["fuerza"] >= minimo]

for persona in ["ana", "luis", "sol"]:
    print(f"Grado de {persona}: {grado(persona)}")

print(f"Amistades con fuerza >= 4: {amistades_fuertes(4)}")
